import base64
import io
import numpy as np
from evaluator.base_agent import BaseAgent

# Paste your NEW NumPy-based Base64 string here
WEIGHTS_BASE64 = ""
class MyAgent(BaseAgent): # Named 'MyAgent' to match your Codabench logs
    def __init__(self, state_size=6, action_size=9):
        super().__init__()
        
        # Load weights from the NumPy string
        try:
            weights_bytes = base64.b64decode(WEIGHTS_BASE64)
            with np.load(io.BytesIO(weights_bytes)) as data:
                self.w1 = data['fc1.weight']
                self.b1 = data['fc1.bias']
                self.w2 = data['fc2.weight']
                self.b2 = data['fc2.bias']
                self.w3 = data['fc3.weight']
                self.b3 = data['fc3.bias']
            print("✅ MyAgent: NumPy weights loaded (Torch-free!)")
        except Exception as e:
            print(f"❌ MyAgent: Failed to load: {e}")

    def relu(self, x):
        return np.maximum(0, x)

    def act(self, observation):
        # 1. Slice and Normalize (exactly like training)
        x = observation[:6].copy()
        x[0:2] /= 128.0
        
        # 2. Manual Forward Pass (Layer 1 -> ReLU -> Layer 2 -> ReLU -> Output)
        # We use .T because PyTorch stores weights as (out_features, in_features)
        h1 = self.relu(np.dot(x, self.w1.T) + self.b1)
        h2 = self.relu(np.dot(h1, self.w2.T) + self.b2)
        q_values = np.dot(h2, self.w3.T) + self.b3
        
        # 3. Return action with highest Q-value
        return int(np.argmax(q_values))

    def reset(self):
        pass

    def seed(self, seed=None):
        if seed is not None:
            np.random.seed(seed)